"""Run-owned native-memory lane over the original command service and gate.

The native stream is parked until the one reply has been written. Actual service
results alone introduce handles; no producer/caller inventory can add offers.
"""
import hashlib
import json

from trial_sdk_command_operation import CommandOperation
from trial_sdk_engine_adapter import CommandTextOutcome, _text_utf8_size
from trial_sdk_incoming import canonical_size_sha256, parse_document
from trial_sdk_shared_coordinator import require


def tools(service):
    # Generated by internal/sdkcontract from addRetrievalTools and its typed
    # arguments; mcpapi's drift test compares the complete declarations. Read
    # the exact pinned, held snapshot, never an ambient mutable source path.
    service._check()
    return json.loads(service._snapshot.read_text('trial_sdk_native_tools.json'))


class NativeMemory:
    def __init__(self, run):
        self.run = run
        self.event = self.operation = None
        self._reply = self._pending_offer = None
        self._offers = {}
        self._initialized = self._notified = False
        self._state = 'idle'
        self._turn = 0

    def bind(self, event):
        require(self._state == 'idle' and self.event is None, 'native_memory_pending')
        self.event = event
        self._state = 'request'

    def _reply_result(self, result):
        self.run._session.memory_reply(self.event.callback.request_id, result)
        self._state = 'writing'

    def _request(self):
        run = self.run
        message = self.event.callback.message
        method, params = message['method'], message.get('params', {})
        if method == 'initialize':
            require(not self._initialized and 'id' in message, 'native_memory_initialize')
            require(set(params) == {'protocolVersion', 'capabilities', 'clientInfo'}
                    and params['protocolVersion'] in ('2024-11-05','2025-03-26','2025-06-18')
                    and type(params['capabilities']) is dict and type(params['clientInfo']) is dict,
                    'native_memory_initialize')
            self._initialized = True
            self._reply_result(dict(protocolVersion=params['protocolVersion'], capabilities={'tools': {}},
                                    serverInfo={'name': 'cairn', 'version': 'sdk-hosted-memory/1'}))
            return
        require(self._initialized, 'native_memory_not_initialized')
        if method == 'notifications/initialized':
            require(not self._notified and not params and 'id' not in message, 'native_memory_notification')
            self._notified = True
            self._reply_result({})
            return
        require(self._notified and 'id' in message, 'native_memory_not_initialized')
        if method == 'tools/list':
            require(not params, 'native_memory_tools_params')
            self._reply_result({'tools': tools(run._service)})
            return
        if method == 'ping':
            require(not params, 'native_memory_ping')
            self._reply_result({})
            return
        require(method == 'tools/call' and set(params) == {'name', 'arguments'}
                and params['name'] in ('cairn_search','cairn_pull')
                and type(params['arguments']) is dict, 'native_memory_call')
        arguments = params['arguments']
        if params['name'] == 'cairn_pull':
            require((arguments.get('receipt_id'), arguments.get('handle')) in self._offers,
                    'native_memory_unoffered')
        service = run._service
        service._check()
        require(service._started and getattr(run._link, '_fixed_launch', None) is service
                and run._link.owner.snapshot()['launched']
                and run._link.owner.snapshot()['wait'] is None, 'native_memory_service')
        state = run._link.transcript.snapshot()
        self.operation = CommandOperation.__new__(CommandOperation)
        CommandOperation.__init__(self.operation, run._link, run._command_quote,
            operation=state['operation'] + 1, lease=state['lease'] + 1,
            deadline_ns=run._deadline, clock=run._clock)
        self.operation.bind_gate(run._coordinator.gate, native=True)
        self.operation.prepare_native('mcp__cairn__' + params['name'], arguments, service._runtime.policy)
        self._state = 'command'

    def _result(self):
        result = self.operation.result()
        require(type(result) is CommandTextOutcome, 'native_memory_command_refused')
        if result.returncode != 0:
            self._reply_result({'isError': True, 'content': [{'type': 'text', 'text': 'Cairn command refused'}]})
            return
        value = parse_document(result.stdout, _text_utf8_size(result.stdout), max_bytes=1024*1024)
        require(value.get('ok') is True and type(value.get('data')) is dict, 'native_memory_response')
        data = value['data']
        params = self.event.callback.message['params']
        if params['name'] == 'cairn_search':
            require(data.get('schema') == 'cairn.agent-search/1' and type(data.get('index')) is list,
                    'native_memory_search_response')
            require(data.get('status') in ('READY', 'SCOPE_EMPTY', 'DEGRADED_NO_EMBEDDINGS')
                    and type(data.get('destination')) is dict
                    and data['destination'].get('name') == 'hosted', 'native_memory_destination')
            # Both Go facades embed the same SemanticPackage and source identity.
            # CLI convenience command strings contain local routes: never expose them.
            data['schema'] = 'cairn.mcp-search/1'
            offers = dict(self._offers)
            for entry in data['index']:
                require(type(entry) is dict and type(entry.get('pull_arguments')) is dict,
                        'native_memory_offer')
                entry.pop('pull_command', None)
                args = entry['pull_arguments']
                require(set(args) == {'request_id','receipt_id','handle'} and
                        args['receipt_id'] == data.get('receipt_id'), 'native_memory_offer')
                key = (args['receipt_id'], args['handle'])
                source = (entry.get('record_id'), entry.get('version'), entry.get('body_sha256'))
                require(all(type(v) is str and v for v in key) and type(source[0]) is str
                        and type(source[1]) is int and source[1] > 0 and type(source[2]) is str
                        and len(source[2]) == 64, 'native_memory_offer')
                require(key not in offers or offers[key] == source, 'native_memory_offer_changed')
                offers[key] = source
            require(canonical_size_sha256([[*k,*v] for k,v in offers.items()])[0] <= 131072,
                    'native_memory_offers_bound')
            self._pending_offer = offers
        else:
            args = params['arguments']
            offer = self._offers[(args['receipt_id'], args['handle'])]
            record = data.get('selection', {}).get('record', {})
            require((record.get('record_id'), record.get('version')) == offer[:2],
                    'native_memory_source_changed')
            if args.get('span') is None:
                body = record.get('body')
                require(type(body) is str and _text_utf8_size(body) <= 32000,
                        'native_memory_result_bound')
                digest = hashlib.sha256()
                for offset in range(0, len(body), 2048):
                    chunk = body[offset:offset+2048].encode('utf-8')
                    digest.update(chunk)
                    chunk = None
                require(digest.hexdigest() == offer[2],
                        'native_memory_source_changed')
            else:
                span = data.get('span', {})
                require(span.get('source_sha256') == offer[2]
                        and span.get('offset') == args['span']['offset'], 'native_memory_source_changed')
        text = json.dumps(data, ensure_ascii=False, separators=(',', ':'), sort_keys=True)
        reply = {'content': [{'type': 'text', 'text': text}], 'isError': False}
        room = params['arguments'].get('memory_budget_bytes') or params['arguments'].get('available_tokens') or 32000
        if params['name'] == 'cairn_search':
            room -= params['arguments'].get('min_pull_bytes') or 0
            if params['arguments'].get('inspection_policy'):
                # The fixed CLI already validates InspectionViewRoom's complete
                # allocation. Preserve its remaining grant beside the MCP view.
                remaining = data.get('bytes_remaining')
                require(type(remaining) is int and 0 <= remaining <= room,
                        'native_memory_inspection_response')
                room -= remaining
        require(canonical_size_sha256(reply)[0] <= min(32000, room), 'native_memory_result_bound')
        self._reply_result(reply)

    def step(self):
        require(self.event is not None, 'native_memory_unbound')
        if self._state == 'request':
            self._request()
        elif self._state == 'command':
            self._turn = 1 - self._turn
            if self._turn:
                self.operation.step()
            else:
                event = self.run._session.step(0)
                require(event.kind in ('idle', 'progress', 'stderr_eof'),
                        'native_memory_session_event')
            if self.operation._closed:
                self._state = 'result'
        elif self._state == 'result':
            self._result()
        elif self._state == 'writing':
            event = self.run._session.step(0)
            require(event.kind in ('idle','progress','stderr_eof','memory_reply_written'),
                    'native_memory_session_event')
            if event.kind == 'memory_reply_written':
                require(event.observation['request_sha256'] == self.event.observation['request_sha256'],
                        'native_memory_reply_binding')
                if self._pending_offer is not None:
                    self._offers, self._pending_offer = self._pending_offer, None
                self._state = 'retiring'
        else:
            require(self._state == 'retiring', 'native_memory_state')
            # Result/encoder/write frames have returned; retained offers are bounded
            # metadata charged to preparation. End all command aliases before release.
            self.event = self._reply = None
            if self.operation is not None:
                self.operation.retire()
                self.operation = None
            self._state = 'idle'
        return self._state
